import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.
    It combines a rotated quadratic bowl with a skewed component and local optima.

    Formula:
    f(x) = quadratic_bowl(x) + skewed_term(x) + local_optima(x)

    Components:
    - quadratic_bowl: A rotated quadratic function.
    - skewed_term: Introduces skewness to the fitness landscape.
    - local_optima: Creates small local optima.
    """
    def quadratic_bowl(x):
        rotation_matrix = np.array([[0.707, -0.707], [0.707, 0.707]])
        x_rotated = np.dot(x, rotation_matrix)
        return np.sum(x_rotated**2)

    def skewed_term(x):
        return np.sum(x**3) * 0.01

    def local_optima(x):
      return np.sum(np.sin(x * 5) * 0.1)

    return quadratic_bowl(x) + skewed_term(x) + local_optima(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function combining a separable function, a non-separable function, and a Gaussian.

    Formula: f(x) = separable_function(x) + non_separable_function(x) + gaussian_component(x)

    - separable_function: sum(abs(x))
    - non_separable_function: (x[0] - x[1])**2
    - gaussian_component: amplitude * exp(-0.5 * ((x[0] - center_x)**2 / sigma_x**2 + (x[1] - center_y)**2 / sigma_y**2))
    """
    def separable_function(x):
        return np.sum(np.abs(x))

    def non_separable_function(x):
        return (x[0] - x[1])**2 * 0.25

    def gaussian_component(x):
         amplitude = 0.1
         center_x = 1.0
         center_y = -1.0
         sigma_x = 2.0
         sigma_y = 2.0

         return amplitude * np.exp(-0.5 * ((x[0] - center_x)**2 / sigma_x**2 + (x[1] - center_y)**2 / sigma_y**2))

    return separable_function(x) + non_separable_function(x) + gaussian_component(x)
